import{_ as t,o,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Flow — OTP Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-6-otp-verification/sequence-flow.md","filePath":"feature/authentication/3-2-6-otp-verification/sequence-flow.md"}'),c={name:"feature/authentication/3-2-6-otp-verification/sequence-flow.md"};function a(d,e,l,s,n,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-otp-verification" tabindex="-1">Sequence Flow — OTP Verification <a class="header-anchor" href="#sequence-flow-—-otp-verification" aria-label="Permalink to &quot;Sequence Flow — OTP Verification&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.2.6). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>ProfilePage (UI)</code>.</li><li><strong>System</strong> — <code>AuthController</code> / <code>AuthService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-otp-verification" tabindex="-1">Flow A — Luồng thực thi chính: OTP Verification <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-otp-verification" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: OTP Verification&quot;">​</a></h2><ol><li>user -&gt; profilepageui: <code>clicks &quot;Verify Phone / Email via OTP&quot;</code></li><li>profilepageui -&gt; authcontroller: <code>POST /api/v1/auth/otp/send (OtpRequest, headers: Bearer accessToken)</code></li><li>authcontroller -&gt; authservice: <code>sendOtp(userId, target)</code></li><li>authservice -&gt; userrepository: <code>findById(userId)</code></li><li>userrepository --&gt; authservice: <code>Optional&lt;User&gt;</code></li><li>authservice -&gt; rediscache: <code>set(&quot;otp:&quot; + userId, otp, 5 min)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice -&gt; mailservice: <code>sendOtpEmail(email, otp)</code></li><li>mailservice --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK</code></li><li>authcontroller --&gt; profilepageui: <code>200 OK</code></li><li>profilepageui --&gt; user: <code>&quot;OTP sent — enter it below&quot;</code></li><li>user -&gt; profilepageui: <code>enters OTP, clicks &quot;Verify&quot;</code></li><li>profilepageui -&gt; authcontroller: <code>POST /api/v1/auth/otp/verify (OtpVerifyRequest, headers: Bearer accessToken)</code></li><li>authcontroller -&gt; authservice: <code>verifyOtp(userId, otp)</code></li><li>authservice -&gt; rediscache: <code>get(&quot;otp:&quot; + userId)</code></li><li>rediscache --&gt; authservice: <code>null / mismatch</code></li><li>authservice --&gt; authcontroller: <code>400 Bad Request (OTP_INVALID)</code></li><li>authcontroller --&gt; profilepageui: <code>400 Bad Request</code></li><li>profilepageui --&gt; user: <code>Show error &quot;Invalid or expired OTP&quot;</code></li><li>rediscache --&gt; authservice: <code>storedOtp (match)</code></li><li>authservice -&gt; rediscache: <code>delete(&quot;otp:&quot; + userId)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice -&gt; userrepository: <code>save(user with verified flag)</code></li><li>userrepository --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK</code></li><li>authcontroller --&gt; profilepageui: <code>200 OK</code></li><li>profilepageui --&gt; user: <code>&quot;Verified successfully&quot;</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const p=t(c,[["render",a]]);export{g as __pageData,p as default};
